/* Emulator test for the key_giveaways rules (first person to claim wins; claims are private). Run by run-giveaway-rules-test.sh */
const NS = 'demo-lvr-default-rtdb', BASE = 'http://127.0.0.1:9000';
const b64u = o => Buffer.from(JSON.stringify(o)).toString('base64url');
const jwt = uid => b64u({ alg: 'none', typ: 'JWT' }) + '.' + b64u({ uid, user_id: uid, sub: uid, iat: Math.floor(Date.now() / 1000) }) + '.';
const TOK = { owner: jwt('TESTOWNER'), treasurer: jwt('TESTTREASURER'), other: jwt('SOMEONE-ELSE') };
async function call(who, method, p, body) {
  const auth = TOK[who] ? '&auth=' + TOK[who] : '';
  const r = await fetch(`${BASE}${p}.json?ns=${NS}${auth}`, { method, headers: Object.assign({ 'Content-Type': 'application/json' }, who === 'admin' ? { Authorization: 'Bearer owner' } : {}), body: body === undefined ? undefined : JSON.stringify(body) });
  return { s: r.status, t: await r.text() };
}
let pass = 0, fail = 0;
const t = async (name, who, method, p, body, allow, expectBody) => {
  const r = await call(who, method, p, body), ok = (r.s === 200) === allow && (expectBody === undefined || r.t === expectBody);
  ok ? pass++ : fail++; console.log((ok ? 'PASS' : 'FAIL') + '  [' + who + '] ' + name + (ok ? '' : '  (HTTP ' + r.s + ' ' + r.t.slice(0, 90) + ')'));
};
const G = '/key_giveaways/abcd1234efgh5678ijkl9012', G2 = '/key_giveaways/zzzz1234efgh5678ijkl9012';
const claim = (extra) => Object.assign({ first: 'Ann', last: 'Lee', email: 'ann@example.com', phone: '7025550100', ig: '@ann.lee', street: '123 Fremont St', city: 'Las Vegas', state: 'NV', zip: '89101', at: { '.sv': 'timestamp' }, consent: true, emailOk: true, smsOk: true, vid: 'abcdefghijklmnop1234', rv: 'v1' }, extra || {});
(async () => {
  const mk = { label: 'Grand opening', keys: 25, createdAt: { '.sv': 'timestamp' } };
  await t('a stranger cannot make a giveaway', 'anon', 'PUT', G, mk, false);
  await t('a signed-in stranger cannot make a giveaway', 'other', 'PUT', G, mk, false);
  await t('the owner makes a giveaway', 'owner', 'PUT', G, mk, true);
  await t('the Treasury PIN account makes a giveaway', 'treasurer', 'PUT', G2, mk, true);
  await t('keys above the limit are refused', 'owner', 'PUT', '/key_giveaways/limit1234limit1234limit', Object.assign({}, mk, { keys: 1e9 }), false);
  await t('fractional keys are refused', 'owner', 'PUT', '/key_giveaways/frac12345frac12345frac1', Object.assign({}, mk, { keys: 2.5 }), false);
  await t('a stranger cannot read the giveaway list', 'anon', 'GET', '/key_giveaways', undefined, false);
  await t('a stranger cannot read a whole giveaway', 'anon', 'GET', G, undefined, false);
  await t('the page can read the label', 'anon', 'GET', G + '/label', undefined, true, '"Grand opening"');
  await t('the page can read the keys', 'anon', 'GET', G + '/keys', undefined, true, '25');
  await t('the page can see nobody has claimed yet', 'anon', 'GET', G + '/claim/at', undefined, true, 'null');
  await t('a claim on a giveaway that does not exist is refused', 'anon', 'PUT', '/key_giveaways/nothere1234nothere1234no/claim', claim(), false);
  await t('a claim without consent is refused', 'anon', 'PUT', G + '/claim', claim({ consent: false }), false);
  await t('a claim with a bad email is refused', 'anon', 'PUT', G + '/claim', claim({ email: 'not-an-email' }), false);
  await t('a claim with a made-up time is refused', 'anon', 'PUT', G + '/claim', claim({ at: 5 }), false);
  await t('a claim with a missing name is refused', 'anon', 'PUT', G + '/claim', { email: 'a@b.co', phone: '7025550100', at: { '.sv': 'timestamp' }, consent: true }, false);
  await t('a claim without email permission is refused', 'anon', 'PUT', G + '/claim', claim({ emailOk: false }), false);
  await t('a claim without text-message permission is refused', 'anon', 'PUT', G + '/claim', claim({ smsOk: false }), false);
  await t('a claim without an Instagram handle is refused', 'anon', 'PUT', G + '/claim', (() => { const x = claim(); delete x.ig; return x; })(), false);
  await t('a claim with a bad Instagram handle is refused', 'anon', 'PUT', G + '/claim', claim({ ig: 'not a handle!' }), false);
  await t('a claim without a street address is refused', 'anon', 'PUT', G + '/claim', (() => { const x = claim(); delete x.street; return x; })(), false);
  await t('a claim from outside Las Vegas is refused', 'anon', 'PUT', G + '/claim', claim({ city: 'Reno' }), false);
  await t('a claim from another state is refused', 'anon', 'PUT', G + '/claim', claim({ state: 'CA' }), false);
  await t('a claim with a non-Las Vegas ZIP is refused', 'anon', 'PUT', G + '/claim', claim({ zip: '90210' }), false);
  await t('a claim with a bad visitor id is refused', 'anon', 'PUT', G + '/claim', claim({ vid: 'x' }), false);
  await t('a claim with extra fields is refused', 'anon', 'PUT', G + '/claim', claim({ paid: true, hack: 1 }), false);
  await t('the FIRST visitor claims it', 'anon', 'PUT', G + '/claim', claim(), true);
  await t('the SECOND visitor is refused', 'anon', 'PUT', G + '/claim', claim({ first: 'Bob', email: 'bob@example.com' }), false);
  await t('nobody can overwrite the claim', 'other', 'PUT', G + '/claim', claim({ first: 'Eve' }), false);
  await t('the page can now see it was claimed', 'anon', 'GET', G + '/claim/at', undefined, true);
  await t('a stranger cannot read who claimed it', 'anon', 'GET', G + '/claim', undefined, false);
  await t('a stranger cannot read the claimed name', 'anon', 'GET', G + '/claim/email', undefined, false);
  await t('the owner can read the claim', 'owner', 'GET', G + '/claim', undefined, true);
  await t('the owner marks the keys as given', 'owner', 'PATCH', G + '/claim', { paid: true, paidAt: { '.sv': 'timestamp' }, wallet: 'Ann Lee' }, true);
  await t('the Treasury PIN account can read the list', 'treasurer', 'GET', '/key_giveaways', undefined, true);
  await t('a stranger cannot delete a claim', 'anon', 'DELETE', G + '/claim', undefined, false);
  // waiting list
  await t('a visitor can join the waiting list after the claim', 'anon', 'PUT', G + '/waitlist/w1', claim({ first: 'Bob', email: 'bob@example.com' }), true);
  await t('a second person can join the waiting list', 'anon', 'PUT', G + '/waitlist/w2', claim({ first: 'Cy', email: 'cy@example.com' }), true);
  await t('a waiting-list entry cannot be overwritten', 'anon', 'PUT', G + '/waitlist/w1', claim({ first: 'Eve' }), false);
  await t('a waiting-list entry needs both permissions', 'anon', 'PUT', G + '/waitlist/w3', claim({ smsOk: false }), false);
  await t('a waiting-list entry must be a Las Vegas address', 'anon', 'PUT', G + '/waitlist/w4', claim({ city: 'Denver' }), false);
  await t('a waiting-list entry for a giveaway that does not exist is refused', 'anon', 'PUT', '/key_giveaways/nothere1234nothere1234no/waitlist/w1', claim(), false);
  await t('a stranger cannot read the waiting list', 'anon', 'GET', G + '/waitlist', undefined, false);
  await t('the owner can read the waiting list', 'owner', 'GET', G + '/waitlist', undefined, true);
  // visitor tracking
  const V = '/key_visits/abcdefghijklmnop1234';
  const vis = (extra) => Object.assign({ page: 'claim', at: { '.sv': 'timestamp' }, secs: 0, g: 'abcd1234efgh5678ijkl9012' }, extra || {});
  await t('a visit can be logged', 'anon', 'PUT', V + '/pg1abcdef', vis(), true);
  await t('a visit with a made-up start time is refused', 'anon', 'PUT', V + '/pg2abcdef', vis({ at: 5 }), false);
  await t('a new visit must start at zero seconds', 'anon', 'PUT', V + '/pg3abcdef', vis({ secs: 50 }), false);
  await t('time on the page can go up', 'anon', 'PATCH', V + '/pg1abcdef', { secs: 47 }, true);
  await t('time on the page cannot go back down', 'anon', 'PATCH', V + '/pg1abcdef', { secs: 3 }, false);
  await t('time on the page has a ceiling', 'anon', 'PATCH', V + '/pg1abcdef', { secs: 99999 }, false);
  await t('the start time cannot be changed', 'anon', 'PATCH', V + '/pg1abcdef', { at: 12345 }, false);
  await t('a bad visitor id is refused', 'anon', 'PUT', '/key_visits/x/pg1abcdef', vis(), false);
  await t('a visit with extra fields is refused', 'anon', 'PUT', V + '/pg4abcdef', vis({ hack: 1 }), false);
  await t('a stranger cannot read the visits', 'anon', 'GET', '/key_visits', undefined, false);
  await t('a stranger cannot read one visitor', 'anon', 'GET', V, undefined, false);
  await t('the owner can read the visits', 'owner', 'GET', '/key_visits', undefined, true);
  await t('the Treasury PIN account can read the visits', 'treasurer', 'GET', '/key_visits', undefined, true);
  await t('a stranger cannot delete a visit', 'anon', 'DELETE', V + '/pg1abcdef', undefined, false);
  // standing waiting list (one entry per email, the key is a SHA-256 of the email)
  const H1 = 'a'.repeat(64), H2 = 'b'.repeat(64);
  await t('a visitor joins the standing waiting list', 'anon', 'PUT', '/key_waitlist/' + H1, claim(), true);
  await t('the same email cannot be added twice', 'anon', 'PUT', '/key_waitlist/' + H1, claim({ first: 'Eve' }), false);
  await t('another person joins', 'anon', 'PUT', '/key_waitlist/' + H2, claim({ first: 'Dee', email: 'dee@example.com' }), true);
  await t('an entry must use a 64-character email fingerprint', 'anon', 'PUT', '/key_waitlist/notahash', claim(), false);
  await t('an entry needs both permissions', 'anon', 'PUT', '/key_waitlist/' + 'c'.repeat(64), claim({ smsOk: false }), false);
  await t('an entry must be a Las Vegas address', 'anon', 'PUT', '/key_waitlist/' + 'd'.repeat(64), claim({ city: 'Phoenix' }), false);
  await t('an entry without a street address is refused', 'anon', 'PUT', '/key_waitlist/' + 'f'.repeat(64), (() => { const x = claim(); delete x.street; return x; })(), false);
  await t('an entry that says yes to trading is accepted', 'anon', 'PUT', '/key_waitlist/' + 'a1'.repeat(32), claim({ trade: true }), true);
  await t('an entry with a trade value that is not true or false is refused', 'anon', 'PUT', '/key_waitlist/' + 'b2'.repeat(32), claim({ trade: 'yes' }), false);
  await t('an entry that confirms an active Instagram account is accepted', 'anon', 'PUT', '/key_waitlist/' + 'a4'.repeat(32), claim({ igActive: true }), true);
  await t('an entry that says the Instagram account is not active is refused', 'anon', 'PUT', '/key_waitlist/' + 'b4'.repeat(32), claim({ igActive: false }), false);
  await t('a stranger cannot mark themselves verified', 'anon', 'PUT', '/key_waitlist/' + 'c3'.repeat(32), claim({ verified: true }), false);
  await t('the owner can mark a person verified', 'owner', 'PATCH', '/key_waitlist/' + H1, { verified: true, verifiedAt: Date.now() }, true);
  await t('an entry with extra fields is refused', 'anon', 'PUT', '/key_waitlist/' + 'e'.repeat(64), claim({ hack: 1 }), false);
  await t('a stranger cannot read the standing waiting list', 'anon', 'GET', '/key_waitlist', undefined, false);
  await t('a stranger cannot read one entry', 'anon', 'GET', '/key_waitlist/' + H1, undefined, false);
  await t('a stranger cannot delete an entry', 'anon', 'DELETE', '/key_waitlist/' + H1, undefined, false);
  const IDEA = (x) => Object.assign({ ig: '@ann.lee', text: 'Add a way to vote on new perks', at: { '.sv': 'timestamp' }, vid: 'abcdefghijklmnop1234', rv: 'v1' }, x || {});
  await t('anyone can send an idea', 'anon', 'PUT', '/key_ideas/' + 'a'.repeat(20), IDEA(), true);
  await t('an idea cannot be overwritten', 'anon', 'PUT', '/key_ideas/' + 'a'.repeat(20), IDEA({ text: 'changed' }), false);
  await t('an idea needs an Instagram handle', 'anon', 'PUT', '/key_ideas/' + 'b'.repeat(20), IDEA({ ig: 'not a handle!' }), false);
  await t('an idea cannot be empty', 'anon', 'PUT', '/key_ideas/' + 'c'.repeat(20), IDEA({ text: 'ab' }), false);
  await t('an idea cannot be huge', 'anon', 'PUT', '/key_ideas/' + 'd'.repeat(20), IDEA({ text: 'x'.repeat(1001) }), false);
  await t('an idea with extra fields is refused', 'anon', 'PUT', '/key_ideas/' + 'e'.repeat(20), IDEA({ hack: 1 }), false);
  await t('an idea needs a long random id', 'anon', 'PUT', '/key_ideas/short', IDEA(), false);
  await t('a stranger cannot read ideas', 'anon', 'GET', '/key_ideas', undefined, false);
  await t('the owner can read ideas', 'owner', 'GET', '/key_ideas', undefined, true);
  await t('the owner can read the standing waiting list', 'owner', 'GET', '/key_waitlist', undefined, true);
  await t('the Treasury PIN account can read it', 'treasurer', 'GET', '/key_waitlist', undefined, true);
  await t('the owner can remove an entry', 'owner', 'DELETE', '/key_waitlist/' + H2, undefined, true);
  // ---- sign-up pause switch, 18+ and rules agreement (2026-11-25) ----
  const P1 = 'e'.repeat(64), P2 = 'f'.repeat(64), P3 = '1'.repeat(64), P4 = '2'.repeat(64), P5 = '3'.repeat(64);
  await t('a visitor can read the sign-up pause switch', 'anon', 'GET', '/key_settings/signupsPaused', undefined, true);
  await t('a visitor cannot read the settings folder', 'anon', 'GET', '/key_settings', undefined, false);
  await t('a visitor cannot flip the pause switch', 'anon', 'PUT', '/key_settings/signupsPaused', true, false);
  await t('a signed-in stranger cannot flip the pause switch', 'other', 'PUT', '/key_settings/signupsPaused', true, false);
  await t('the pause switch only takes true or false', 'owner', 'PUT', '/key_settings/signupsPaused', 'yes', false);
  await t('the new sign-up (18+, rules agreed, form v2) is accepted', 'anon', 'PUT', '/key_waitlist/' + P1, claim({ email: 'p1@example.com', ageOk: true, rulesOk: true, rv: 'v2' }), true);
  await t('an old-form sign-up (no ageOk, rulesOk) is still accepted', 'anon', 'PUT', '/key_waitlist/' + P2, claim({ email: 'p2@example.com' }), true);
  await t('ageOk false is refused', 'anon', 'PUT', '/key_waitlist/' + P3, claim({ email: 'p3@example.com', ageOk: false }), false);
  await t('rulesOk false is refused', 'anon', 'PUT', '/key_waitlist/' + P3, claim({ email: 'p3@example.com', rulesOk: false }), false);
  await t('the owner pauses sign-ups', 'owner', 'PUT', '/key_settings/signupsPaused', true, true);
  await t('while paused a visitor cannot join', 'anon', 'PUT', '/key_waitlist/' + P4, claim({ email: 'p4@example.com', ageOk: true, rulesOk: true }), false);
  await t('while paused the owner can still edit an entry', 'owner', 'PATCH', '/key_waitlist/' + P1, { verified: true, verifiedAt: 1 }, true);
  await t('while paused the PIN account can still edit an entry', 'treasurer', 'PATCH', '/key_waitlist/' + P1, { verified: false, verifiedAt: 2 }, true);
  await t('the PIN account can open sign-ups again', 'treasurer', 'PUT', '/key_settings/signupsPaused', false, true);
  await t('after opening a visitor can join', 'anon', 'PUT', '/key_waitlist/' + P4, claim({ email: 'p4@example.com', ageOk: true, rulesOk: true }), true);
  await t('removing the switch also leaves sign-ups open', 'owner', 'DELETE', '/key_settings/signupsPaused', undefined, true);
  await t('with no switch a visitor can join', 'anon', 'PUT', '/key_waitlist/' + P5, claim({ email: 'p5@example.com', ageOk: true, rulesOk: true }), true);
  await t('a visitor cannot self-verify on joining', 'anon', 'PUT', '/key_waitlist/' + '4'.repeat(64), claim({ email: 'p6@example.com', verified: true, verifiedAt: 3 }), false);
  console.log(`\n${pass} passed, ${fail} failed`); process.exit(fail ? 1 : 0);
})();
